<template><section class="umo"><header><h2>{{ $t("成员 #") }}{{memberId}} {{ $t("· 用户全景") }}</h2><button @click="$emit('close')">{{ $t("关闭") }}</button></header><p v-if="loading">{{ $t("正在获取账户资料…") }}</p><p v-if="error" role="alert">{{ $t(error) }} <button @click="load">{{ $t("重试") }}</button></p><template v-if="profile"><div class="umo-grid"><article><h3>{{ $t("新 UMI") }}</h3><p>{{ $t("Deepro 用户") }} {{profile.member.member.user_id}} · {{profile.member.member.member_code}}</p><p>{{ $t("可提收益") }} {{fmt(profile.member.income?.available||'0')}} UMI</p><p>{{ $t("钱包") }} {{profile.member.wallet_available?fmt(profile.member.wallet_umi):$t('暂不可取得')}} UMI</p><p>{{ $t("待激活本金") }} {{fmt(profile.member.pending_principal_umi)}} UMI</p><p>{{ $t("剩余额度") }} {{fmt(profile.member.cycle_summary?.active_remaining_umi)}} UMI</p><p>{{ $t("股票积分") }} {{fmt(profile.member.pending_points)}} {{ $t("· 股票份额") }} {{fmt(profile.member.stock_balance_shares)}}</p></article><article><h3>{{ $t("原档案与接续") }}</h3><p>{{ $t("原 UID") }} {{profile.legacy_id||$t('尚未绑定')}}</p><p>{{profile.account_merge?$t('已接续 · ')+fmt(profile.account_merge.principal_umi)+' UMI':$t('尚无本金接续凭证')}}</p><a v-if="profile.legacy_id" :href="'/exchange-control-panel/umi/operations?tab=archive&legacy_account='+profile.legacy_id">{{ $t("查询原档案与分页流水") }}</a><p v-if="profile.captured_account">{{ $t("采集批次 #") }}{{profile.captured_account.batch_id}} {{ $t("· 核对本金") }} {{fmt(profile.captured_account.principal_umi)}} UMI</p><p>{{ $t("采集余额用于核对，不与当前资产重复相加。") }}</p><details v-if="profile.captured_account"><summary>{{ $t("采集时的原始资料") }}</summary><pre>{{JSON.stringify(profile.captured_account.source,null,2)}}</pre></details></article></div><umi-team-overview :admin-view="true" :member-id="memberId"/><nav><a v-for="(name,key) in records" :key="key" :href="'/exchange-control-panel/umi/operations?tab=records&record_dataset='+key+'&record_member='+memberId">{{name}}</a><a :href="'/exchange-control-panel/umi/operations?tab=records&record_dataset=releases&record_root='+memberId">{{ $t("伞下收益及导出") }}</a></nav></template></section></template>
<script>
import UmiLocale from '@/Functions/UmiLocale';
import axios from 'axios';import UmiTeamOverview from '@/Components/UmiTeamOverview';import {formatUmi} from '@/Functions/UmiDisplay';
export default {mixins:[UmiLocale],components:{UmiTeamOverview},props:{memberId:[Number,String]},data(){return{profile:null,error:'',loading:false,sequence:0,records:{cycles:'全部轮次',withdrawals:'全部提取订单',lots:'销毁凭证',points:'股票积分',stock_moves:'股票份额流水'}};},mounted(){this.load();},watch:{memberId(){this.load();}},methods:{fmt:formatUmi,async load(){const sequence=++this.sequence;this.loading=true;this.error='';this.profile=null;try{const r=await axios.get('/exchange-control-panel/umi/operations/member',{params:{member_id:this.memberId}});if(sequence===this.sequence)this.profile=r.data;}catch(e){if(sequence===this.sequence)this.error=e.response?.data?.message||'获取账户资料失败。';}finally{if(sequence===this.sequence)this.loading=false;}}}};
</script>
<style scoped>.umo{padding:22px;border:1px solid #cfdfd3;border-radius:18px;background:#fff;margin:18px 0}.umo header{display:flex;justify-content:space-between}.umo h2{font-size:21px}.umo-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.umo p{color:#526b5b}.umo a{color:#14733b}.umo nav{display:flex;flex-wrap:wrap;gap:15px;margin-top:16px}.umo pre{max-height:320px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.umo button{padding:8px 12px;border:1px solid #c5d9cb;border-radius:8px;background:#eef8f1}body.dark .umo{background:#202a24;color:#edf3ee;border-color:#3c4a40}body.dark .umo p{color:#b6c6ba}body.dark .umo a{color:#80d69a}body.dark .umo button{background:#2a3b30;color:#d3e9da}@media(max-width:650px){.umo-grid{grid-template-columns:1fr}}</style>
